const $=id => document.getElementById(id);
const make=(tag,className,text) => { const e=document.createElement(tag); if (className) e.className=className; if (text!==undefined) e.textContent=text; return e; };
let ctx; let composerUI; let documentUI; let datasetUI; let modelConversionUI; let activePanel='general'; let recording; let speechAbort; let pollCount=0; let adapterSignature=''; const namedJobs=new Set();
const number=(label,key,min,max,step=1) => `<label>${label}<input type="number" data-setting="${key}" min="${min}" max="${max}" step="${step}"></label>`;
const toggle=(label,key,help='') => `<label class="toggle-row"><span>${label}<small>${help}</small></span><input type="checkbox" data-setting="${key}"></label>`;
const save='<button type="submit" class="primary-button">Save changes</button>';
function download(filename,content,type='application/json') { const url=URL.createObjectURL(new Blob([content],{ type })); const a=make('a'); a.href=url; a.download=filename; a.click(); setTimeout(() => URL.revokeObjectURL(url),1000); }
function button(label,action,className='secondary-button') { const b=make('button',className,label); b.type='button'; b.onclick=async () => { b.disabled=true; try { await action(); } catch (error) { ctx.fail(error); } finally { b.disabled=false; } }; return b; }
async function patch(values) { await ctx.api('/api/settings',{ method:'PATCH',body:values }); await ctx.refresh(); ctx.toast(values.theme!==undefined || values.fontSize!==undefined ? 'Appearance saved.' : 'Settings saved. Reload the model for inference hardware changes.'); }
function values(form) { const out={}; form.querySelectorAll('[data-setting]').forEach(e => { out[e.dataset.setting]=e.type==='checkbox' ? e.checked : e.type==='number' ? Number(e.value) : e.value; }); return out; }
function panel(id,title,description,html) { const e=make('section','settings-panel'); e.id=`panel-${id}`; e.hidden=true; const head=make('div','settings-heading'); head.append(make('div','page-eyebrow','FORGE / SETTINGS'),make('h2','',title),make('p','page-description',description)); e.append(head); const content=make('div','settings-content'); content.innerHTML=html; e.append(content); return e; }
