    sessions:panel('sessions','Keep your conversations.','Rename, fork, archive, restore, export, and import saved chats.',`<form class="feature-form" data-save-settings>${toggle('Rename a fork after its first new message','renameAfterFork')}${save}</form><div class="action-row"><button id="session-rename" class="secondary-button">Rename current</button><button id="session-fork" class="secondary-button">Fork current</button><button id="session-archive" class="secondary-button">Archive current</button><button id="session-export" class="secondary-button">Export JSON</button><button id="session-export-md" class="secondary-button">Export Markdown</button><label class="secondary-button file-pick">Import chat<input id="session-import" type="file" accept=".json" hidden></label></div><div class="settings-section"><h3>Current session notes</h3><p>Saved with this chat and sent with its system prompt on each request.</p><textarea id="session-memory" rows="5" maxlength="12000" placeholder="Preferences, decisions, or facts to remember in this session."></textarea><button id="session-memory-save" class="secondary-button">Save session notes</button></div><h3>Archived sessions</h3><div id="archived-sessions" class="feature-list"></div>`),
    developer:panel('developer','Under the hood.','Export diagnostics, inspect runtime output, and open desktop developer tools.',`<div class="action-row"><button id="developer-refresh" class="secondary-button">Refresh diagnostics</button><button id="developer-export" class="secondary-button">Export diagnostics</button><button id="developer-tools" class="secondary-button">Toggle developer tools</button></div><pre id="diagnostics" class="feature-log">Select Refresh diagnostics.</pre>`),
    mcp:panel('mcp','Connect your tools.','Connect MCP servers over stdio or Streamable HTTP. External tool calls always need approval.',`<form id="mcp-form" class="feature-form"><label>Server name<input id="mcp-name" required></label><label>Transport<select id="mcp-transport"><option value="stdio">Local command (stdio)</option><option value="http">Streamable HTTP</option></select></label><label>Executable or command<input id="mcp-command" placeholder="Path to an MCP server executable"></label><label>Arguments (JSON array)<textarea id="mcp-args" rows="2">[]</textarea></label><label>HTTP endpoint<input id="mcp-url" placeholder="http://127.0.0.1:8000/mcp"></label><label>HTTP bearer key, if required<input id="mcp-key" type="password" autocomplete="off"></label><button class="primary-button">Add server</button></form><p class="feature-note">Connecting a local server runs the command you configured. MCP servers have their own permissions; their tools are not confined to the Forge project folder. OAuth-only servers require separate authentication and are not supported by this key-based connection form.</p><div id="mcp-list" class="feature-list"></div>`),
