  const vision=make('form','feature-form'); vision.dataset.saveSettings=''; vision.innerHTML='<h3>Vision / images</h3><label>Matching multimodal projector<div class="input-row"><input data-setting="projectorPath" placeholder="Optional mmproj.gguf path"><button type="button" data-pick-setting="projectorPath" data-kind="model" class="secondary-button">Browse</button></div></label>'+number('Maximum image tokens','imageTokens',256,4096)+save+'<p class="feature-note">Choose the matching projector from the same model family/publisher, then reload. Forge runs the projector on CPU to preserve VRAM. Save a per-model preset below, or clear this path before loading a different model. Start with 4,096 context tokens for images. Memory checks include the projector.</p>'; panels.defaults.querySelector('.settings-content').append(vision);
  panels.chat=panel('chat','Normal chat.','A general assistant, separate from project sessions and workspace tools.',`<form class="feature-form" data-save-settings><label>Chat system prompt<textarea data-setting="chatSystemPrompt" rows="7" maxlength="16000"></textarea></label><small>Only used by the Chat tab. Enabled skills and this chat’s own saved notes still apply. Workspace instructions and project tool history stay in Workspace.</small>${save}</form>`);
  const workspacePrompt=form.querySelector('#setting-systemPrompt'); workspacePrompt.parentElement.firstChild.textContent='Workspace system instructions'; workspacePrompt.parentElement.nextElementSibling.textContent='Applies to Workspace sessions. Configure normal conversation separately in Settings → Chat.';
  for (const e of Object.values(panels)) body.append(e);
