  for(const theme of THEMES){const option=make('option','',theme.name);option.value=theme.id;themes.append(option);const card=button('',()=>patch({theme:theme.id,fontSize:theme.fontSize}),'palette-card');card.setAttribute('aria-label',theme.name);card.dataset.palette=theme.id;card.dataset.themeChoice=theme.id;const preview=make('div','theme-preview');preview.setAttribute('aria-hidden','true');preview.innerHTML='<div class="theme-preview-sidebar"><i></i><i></i><i></i></div><div class="theme-preview-main"><span>How can I help?</span><i></i><i></i><div class="theme-preview-composer">Message Forge <b>↑</b></div></div>';card.append(preview,make('strong','',theme.name),make('small','',theme.description));palettes.append(card);}panels.appearance.querySelector('.settings-content').prepend(palettes);
  themes.onchange=()=>{panels.appearance.querySelector('[data-setting="fontSize"]').value=THEMES.find(theme=>theme.id===themes.value).fontSize;};
