  panels.general.querySelector('.settings-content').append(button('Register Forge in the app menu',async () => { if (!window.desktop) throw new Error('This is available in the installed desktop app.'); ctx.toast(await window.desktop.installShortcut()); }));
  const maintenance=make('section','settings-section');maintenance.innerHTML='<h3>Storage and health</h3><p>Check local tools and preview older preparation files and checkpoints. Original datasets, chats, models, and the latest checkpoints are kept.</p><div class="action-row"><button type="button" id="storage-check" class="secondary-button">Check storage and health</button><button type="button" id="storage-clean" class="secondary-button" disabled>Delete selected</button></div><p id="storage-health" class="feature-note" role="status"></p><div id="storage-candidates" class="feature-list"></div>';panels.sessions.querySelector('.settings-content').append(maintenance);
  let cleanupCandidates=[];
  async function refreshStorage(){const preview=await ctx.api('/api/maintenance');cleanupCandidates=preview.items;const h=preview.health;$('storage-health').textContent=`Model folder: ${h.modelFolder?'available':'missing'} · Model engine: ${h.runtime?'available':'not installed'} · Training tools: ${h.trainingEnvironment?'available':'not installed'} · Conversion tools: ${h.conversionEnvironment?'available':'not installed'}\n${(preview.totalBytes/1024**2).toFixed(1)} MiB in older optional files.`;const list=$('storage-candidates');list.replaceChildren();for(const item of cleanupCandidates){const label=make('label','storage-candidate');const check=make('input');check.type='checkbox';check.dataset.id=item.id;check.onchange=()=>{$('storage-clean').disabled=!list.querySelector('input:checked');};label.append(check,make('span','',`${item.name} · ${(item.bytes/1024**2).toFixed(1)} MiB`));list.append(label);}if(!cleanupCandidates.length)list.append(make('p','feature-note','No older optional files are available to clean.'));$('storage-clean').disabled=true;}
