  $('composer-skills').textContent=(data.skills || []).filter(s => s.enabled).length ? `Skills: ${(data.skills || []).filter(s => s.enabled).map(s => s.name).join(', ')}` : '';
  document.querySelectorAll('[data-setting]').forEach(e => { const v=data.settings[e.dataset.setting] ?? fallback[e.dataset.setting]; if (e.type==='checkbox') e.checked=Boolean(v); else if (v!==undefined) e.value=v; });
  $('chat-folder-path').textContent=data.storage?.sessionDir || data.settings.sessionDir;
  $('quick-execution').value=data.settings.executionMode;
  for(const id of ['quick-execution','execution-mode']) for(const value of ['gpu','hybrid']) {const option=$(id).querySelector(`option[value="${value}"]`);if(option)option.hidden=Array.isArray(data.runtimeDevices) && !data.runtimeDevices.length && data.settings.executionMode!==value;}
  renderRuntime(data);
  const usage=data.usage || []; const input=usage.reduce((a,u) => a+(u.prompt_tokens || 0),0); const output=usage.reduce((a,u) => a+(u.completion_tokens || 0),0);
  $('usage-stats').replaceChildren(stat('Reported input tokens',input.toLocaleString()),stat('Reported output tokens',output.toLocaleString()),stat('Saved sessions',data.sessions.length));
  $('usage-list').replaceChildren(); for (const u of usage.slice(-12).reverse()) $('usage-list').append(row(u.model || 'Local model',`${new Date(u.created).toLocaleString()} · ${u.prompt_tokens || 0} input / ${u.completion_tokens || 0} output`));
  const current=ctx.session(); $('session-memory').value=current?.memory || ''; $('session-memory').disabled=!current;
  for (const id of ['session-rename','session-fork','session-archive','session-export','session-export-md','session-memory-save']) $(id).disabled=!current || ctx.busy();
  $('archived-sessions').replaceChildren(); const archived=data.sessions.filter(s => s.archived); if (!archived.length) $('archived-sessions').append(make('p','feature-note','No archived sessions.'));
  for (const s of archived) { const r=row(s.title,`${s.messageCount || 0} messages · saved on disk`); r.append(button('Restore',async () => { await ctx.api('/api/session/update',{ method:'POST',body:{ id:s.id,archived:false } }); await ctx.refresh(); })); $('archived-sessions').append(r); }
  renderSkills(data); renderMcp(data); renderDevices(data); renderInstances(data); renderDownloads(data.downloads || []); renderApi(data.localApi); renderTrainer(data.trainer); renderAdapters(data.loras);
