function renderImages() { composerUI.renderImages(); }

async function pick(kind,current='') { return window.desktop ? kind==='folder' ? window.desktop.chooseFolder() : window.desktop.chooseFile(kind) : ctx.askPath(`Choose ${kind}`,'Enter the absolute path on this computer.',current); }
async function sessionUpdate(body) { const current=ctx.session(); if (!current) throw new Error('Open a session first.'); const result=await ctx.api('/api/session/update',{ method:'POST',body:{ id:current.id,...body } }); await ctx.refresh(); return result; }
async function transcript(wav) { $('voice-status').textContent='Transcribing locally…'; $('voice-cancel-transcription').hidden=false; speechAbort=new AbortController(); try { let binary=''; const bytes=new Uint8Array(wav); for (let i=0;i<bytes.length;i+=0x8000) binary+=String.fromCharCode(...bytes.subarray(i,i+0x8000)); const response=await fetch('/api/voice/transcribe',{ method:'POST',headers:{ 'Content-Type':'application/json','X-Local-Desk-Token':ctx.token },body:JSON.stringify({ wav:btoa(binary) }),signal:speechAbort.signal }); const result=await response.json(); if (!response.ok) throw new Error(result.error); $('voice-transcript').value=result.text; $('voice-status').textContent='Transcription complete.'; } catch (error) { $('voice-status').textContent=error.name==='AbortError' ? 'Transcription cancelled.' : error.message; } finally { speechAbort=null; $('voice-cancel-transcription').hidden=true; } }
function wavBuffer(samples,rate) { const length=Math.floor(samples.length*16000/rate); const buffer=new ArrayBuffer(44+length*2); const v=new DataView(buffer); const text=(p,s) => { for (let i=0;i<s.length;i++) v.setUint8(p+i,s.charCodeAt(i)); }; text(0,'RIFF'); v.setUint32(4,36+length*2,true); text(8,'WAVE'); text(12,'fmt '); v.setUint32(16,16,true); v.setUint16(20,1,true); v.setUint16(22,1,true); v.setUint32(24,16000,true); v.setUint32(28,32000,true); v.setUint16(32,2,true); v.setUint16(34,16,true); text(36,'data'); v.setUint32(40,length*2,true); for (let i=0;i<length;i++) { const x=samples[Math.min(samples.length-1,Math.floor(i*rate/16000))]; v.setInt16(44+i*2,Math.max(-1,Math.min(1,x))*32767,true); } return buffer; }
async function record() {
  if (recording) { const current=recording; recording=null; clearTimeout(current.timer); current.processor.disconnect(); current.source.disconnect(); current.stream.getTracks().forEach(t => t.stop()); const samples=new Float32Array(current.count); let cursor=0; for (const chunk of current.chunks) { samples.set(chunk,cursor); cursor+=chunk.length; } const rate=current.audio.sampleRate; await current.audio.close(); $('voice-record').textContent='Record microphone'; $('voice-cancel').hidden=true; await transcript(wavBuffer(samples,rate)); return; }
  const settings=ctx.state.data.settings; if (!settings.voiceRuntimePath || !settings.voiceModelPath) throw new Error('Configure and save a local Whisper runtime and model first.');
  const stream=await navigator.mediaDevices.getUserMedia({ audio:true,video:false }); const audio=new AudioContext(); const source=audio.createMediaStreamSource(stream); const processor=audio.createScriptProcessor(4096,1,1); recording={ stream,audio,source,processor,chunks:[],count:0 }; processor.onaudioprocess=e => { if (recording) { const chunk=new Float32Array(e.inputBuffer.getChannelData(0)); recording.chunks.push(chunk); recording.count+=chunk.length; } }; source.connect(processor); processor.connect(audio.destination); recording.timer=setTimeout(() => record().catch(ctx.fail),120000); $('voice-record').textContent='Stop & transcribe'; $('voice-cancel').hidden=false; $('voice-status').textContent='Recording · maximum 2 minutes. Click Stop & transcribe when finished.';
}
function bind() {
  document.querySelectorAll('[data-save-settings]').forEach(form => { form.onsubmit=async e => { e.preventDefault(); try { await patch(values(form)); } catch (error) { ctx.fail(error); } }; });
  document.querySelectorAll('[data-pick-setting]').forEach(b => { b.onclick=async () => { try { const field=b.parentElement.querySelector('[data-setting]'); const value=await pick(b.dataset.kind,field.value); if (value) field.value=value; } catch (error) { ctx.fail(error); } }; });
  $('open-chat-folder').onclick=() => window.desktop ? window.desktop.openStorage('chats').catch(ctx.fail) : ctx.toast(ctx.state.data.settings.sessionDir);
  $('change-chat-folder').onclick=async () => { try { const path=await pick('folder',ctx.state.data.settings.sessionDir); if (path) { await ctx.api('/api/storage/chats',{ method:'POST',body:{ path } }); await ctx.refresh(); ctx.toast('Chat folder changed. Existing chats were copied.'); } } catch (error) { ctx.fail(error); } };
  $('open-releases').onclick=() => window.desktop ? window.desktop.releasePage().catch(ctx.fail) : ctx.toast('https://github.com/SinghAbhinav04/Forge/releases');
  $('runtime-form').onsubmit=async e => { e.preventDefault(); try { await patch(values(e.target)); } catch (error) { ctx.fail(error); } };
  $('execution-mode').onchange=() => { const mode=$('execution-mode').value; $('execution-help').textContent=mode==='auto' ? 'Forge chooses a safe CPU or GPU setting for the selected runtime.' : mode==='cpu' ? 'Use CPU and system RAM.' : mode==='gpu' ? 'Offload all model layers. Free VRAM must be sufficient.' : 'Split model layers between GPU/VRAM and CPU/RAM.'; };
  $('quick-execution').onchange=async e => { try { await patch({ executionMode:e.target.value }); } catch (error) { ctx.fail(error); } };
  $('runtime-open').onclick=() => { ctx.showView('settings'); selectSettings('runtime'); };
  $('cancel-load').onclick=async () => { try { await ctx.api('/api/model/unload',{ method:'POST',body:{} }); await ctx.refresh(); } catch (error) { ctx.fail(error); } };
  $('reload-model').onclick=async () => { try { const model=ctx.state.data.runtime.model; await patch(values($('runtime-form'))); await ctx.api('/api/model/unload',{ method:'POST',body:{} }); await ctx.api('/api/model/load',{ method:'POST',body:{ path:model.path } }); await ctx.refresh(); } catch (error) { ctx.fail(error); } };
  $('save-model-preset').onclick=async () => { try { const path=$('preset-model').value; if (!path) throw new Error('Choose a model.'); await ctx.api('/api/model/defaults',{ method:'POST',body:{ path,settings:ctx.state.data.settings } }); ctx.toast('Per-model defaults saved.'); } catch (error) { ctx.fail(error); } };
  $('session-rename').onclick=async () => { try { const title=await ctx.askPath('Rename session','Enter a new name.',ctx.session()?.title || ''); if (title) await sessionUpdate({ title }); } catch (error) { ctx.fail(error); } };
  $('session-fork').onclick=async () => { try { const s=await ctx.api('/api/session/fork',{ method:'POST',body:{ id:ctx.session()?.id } }); await ctx.refresh(); await ctx.selectSession(s.id); } catch (error) { ctx.fail(error); } };
  $('session-archive').onclick=async () => { try { await sessionUpdate({ archived:true }); await ctx.newSession(); ctx.toast('Session archived. Its files remain saved.'); } catch (error) { ctx.fail(error); } };
  for (const [id,format] of [['session-export','json'],['session-export-md','markdown']]) $(id).onclick=async () => { try { const result=await ctx.api(`/api/session/export?id=${encodeURIComponent(ctx.session().id)}&format=${format}`); download(result.filename,result.content); } catch (error) { ctx.fail(error); } };
  $('session-memory-save').onclick=async () => { try { await sessionUpdate({ memory:$('session-memory').value }); ctx.toast('Session notes saved.'); } catch (error) { ctx.fail(error); } };
  $('session-import').onchange=async e => { try { const f=e.target.files[0]; if (!f) return; const imported=await ctx.api('/api/session/import',{ method:'POST',body:{ workspaceId:ctx.state.workspaceId,document:JSON.parse(await f.text()) } }); await ctx.refresh(); await ctx.selectSession(imported.id); } catch (error) { ctx.fail(error); } finally { e.target.value=''; } };
  $('export-usage').onclick=() => { const escape=s => `"${String(s ?? '').replaceAll('"','""')}"`; download('forge-usage.csv','date,model,source,prompt_tokens,completion_tokens\n'+(ctx.state.data.usage || []).map(u => [new Date(u.created).toISOString(),u.model,u.source,u.prompt_tokens,u.completion_tokens].map(escape).join(',')).join('\n'),'text/csv'); };
  $('developer-refresh').onclick=() => refreshDiagnostics().catch(ctx.fail); $('developer-export').onclick=async () => { try { download('forge-diagnostics.json',JSON.stringify(await refreshDiagnostics(),null,2)); } catch (error) { ctx.fail(error); } }; $('developer-tools').onclick=() => window.desktop?.toggleDevtools().catch(ctx.fail);
  $('skill-form').onsubmit=async e => { e.preventDefault(); try { await ctx.api('/api/skills',{ method:'POST',body:{ id:$('skill-id').value || undefined,name:$('skill-name').value,instructions:$('skill-instructions').value,enabled:$('skill-enabled').checked } }); e.target.reset(); await ctx.refresh(); ctx.toast('Skill saved.'); } catch (error) { ctx.fail(error); } };
  $('skill-import').onchange=async e => { try { const file=e.target.files[0]; if (!file) return; if (file.size>64000) throw new Error('Skill file must be under 64,000 bytes.'); const instructions=await file.text(); await ctx.api('/api/skills',{ method:'POST',body:{ name:file.name.replace(/\.(md|txt)$/i,''),instructions,enabled:true } }); await ctx.refresh(); ctx.toast('Skill imported and enabled for the next message.'); } catch (error) { ctx.fail(error); } finally { e.target.value=''; } };
  $('mcp-form').onsubmit=async e => { e.preventDefault(); try { await ctx.api('/api/mcp/save',{ method:'POST',body:{ name:$('mcp-name').value,transport:$('mcp-transport').value,command:$('mcp-command').value,args:JSON.parse($('mcp-args').value),url:$('mcp-url').value,key:$('mcp-key').value } }); $('mcp-key').value=''; await ctx.refresh(); } catch (error) { ctx.fail(error); } };
  $('device-form').onsubmit=async e => { e.preventDefault(); try { await ctx.api('/api/connections',{ method:'POST',body:{ name:$('device-name').value,base:$('device-base').value,key:$('device-key').value } }); e.target.reset(); await ctx.refresh(); } catch (error) { ctx.fail(error); } };
  $('explore-form').onsubmit=async e => { e.preventDefault(); $('explore-status').textContent='Searching Hugging Face…'; try { const results=await ctx.api(`/api/hub/search?q=${encodeURIComponent($('explore-query').value)}`); $('explore-results').replaceChildren(); for (const model of results) { const r=row(model.id,`${(model.downloads || 0).toLocaleString()} downloads`); r.append(button('View model card',async()=>{const url='https://huggingface.co/'+model.id.split('/').map(encodeURIComponent).join('/');if(window.desktop?.openExternal)await window.desktop.openExternal(url);else window.open(url,'_blank','noopener,noreferrer');},'text-button')); r.append(button('Browse GGUF files',async () => { const files=await ctx.api(`/api/hub/files?repo=${encodeURIComponent(model.id)}`); const listing=make('div','hub-files'); for (const f of files) { const entry=row(f.name,`${f.kind==='projector' ? 'Vision projector' : 'Model'} · ${f.bytes ? (f.bytes/1024**3).toFixed(2)+' GiB' : 'Size unknown'} · ${f.license ? 'Reported license: '+f.license : 'License not reported'}${!f.sha256 ? ' · no verified download available' : ''}`); const estimate=f.cpuEstimate; const labels={possible:'CPU estimate: may fit',tight:'CPU estimate: tight fit',unlikely:'CPU estimate: unlikely to fit',unknown:'Fit unknown'}; const note=make('small','feature-note',estimate ? `${labels[estimate.status] || labels.unknown}${Number.isFinite(estimate.ramGiB) ? ` · approximately ${estimate.ramGiB.toFixed(1)} GiB RAM plus ${estimate.reserveGiB.toFixed(1)} GiB reserved` : ''}. ${estimate.reason} Check the fit again after download.` : 'Fit unknown; check again after download.'); entry.querySelector('.feature-row-info').append(note); const b=button('Download',async () => { await ctx.api('/api/downloads/start',{ method:'POST',body:{ repo:model.id,file:f.name } }); await ctx.refresh(); }); b.disabled=!f.sha256; entry.append(b); listing.append(entry); } r.querySelector('.hub-files')?.remove(); r.append(listing); })); $('explore-results').append(r); } $('explore-status').textContent=results.length ? `${results.length} repositories` : 'No repositories found.'; } catch (error) { $('explore-status').textContent=error.message; } };
  for (const [id,action] of [['api-start','start'],['api-stop','stop']]) $(id).onclick=async () => { try { const api=await ctx.api('/api/local-api/control',{ method:'POST',body:{ action } }); ctx.state.data.localApi=api; renderApi(api); } catch (error) { ctx.fail(error); } };
  $('api-key-show').onclick=async () => { try { const result=await ctx.api('/api/local-api/key'); $('api-key-value').value=result.key; $('api-key-value').type=$('api-key-value').type==='password' ? 'text' : 'password'; } catch (error) { ctx.fail(error); } };
  $('voice-record').onclick=() => record().catch(ctx.fail); $('voice-cancel').onclick=async () => { const current=recording; recording=null; if (current) { clearTimeout(current.timer); current.processor.disconnect(); current.source.disconnect(); current.stream.getTracks().forEach(t => t.stop()); await current.audio.close(); } $('voice-record').textContent='Record microphone'; $('voice-cancel').hidden=true; $('voice-status').textContent='Recording cancelled.'; };
  $('voice-wav').onchange=async e => { const file=e.target.files[0]; if (file) { if (file.size>8*1024**2) return ctx.fail(new Error('WAV must be under 8 MiB.')); await transcript(await file.arrayBuffer()); } e.target.value=''; };
  $('voice-cancel-transcription').onclick=() => speechAbort?.abort(); $('voice-use').onclick=() => { $('prompt').value=$('voice-transcript').value; $('prompt').dispatchEvent(new Event('input')); ctx.showView(ctx.state.scope); $('prompt').focus(); };
  $('voice-speak').onclick=() => { const text=ctx.session()?.messages?.filter(m => m.role==='assistant').at(-1)?.content; if (!text) return ctx.fail(new Error('Open a session with an assistant reply first.')); const voice=speechSynthesis.getVoices().find(v => v.localService); if (!voice) return ctx.fail(new Error('No local system speech voice is available. Install one through your OS settings.')); speechSynthesis.cancel(); const utterance=new SpeechSynthesisUtterance(text); utterance.voice=voice; speechSynthesis.speak(utterance); }; $('voice-stop-speaking').onclick=() => speechSynthesis.cancel();
  $('training-check').onclick=async () => { try { $('training-engine-detail').textContent='Checking Python environment…'; const env=await ctx.api('/api/trainer/environment'); $('training-engine-label').textContent=env.installed ? 'Training engine installed' : 'Training engine not installed'; $('training-engine-detail').textContent=env.installed ? `PyTorch ${env.torch} · CUDA ${env.cuda ? 'available' : 'unavailable'} · Metal ${env.mps ? 'available' : 'unavailable'}\n${env.python}` : 'Install the optional CPU engine, or configure this environment separately. It requires Python 3.10+.'; } catch (error) { ctx.fail(error); } };
  $('training-install').onclick=async () => { try { renderTrainer(await ctx.api('/api/trainer/install',{ method:'POST',body:{} })); } catch (error) { ctx.fail(error); } };
  $('train-browse-base').onclick=async () => { try { const value=await pick('folder',$('train-base').value); if (value) $('train-base').value=value; } catch (error) { ctx.fail(error); } }; $('train-browse-dataset').onclick=async () => { try { const value=await pick('dataset',$('train-dataset').value); if (value) { $('train-dataset').value=value; $('train-dataset').dispatchEvent(new Event('input')); } } catch (error) { ctx.fail(error); } };
  $('training-form').onsubmit=async e => { e.preventDefault(); try { const body={ ...datasetUI.confirmed(),baseModel:$('train-base').value,dataset:$('train-dataset').value,device:$('train-device').value,gradientCheckpointing:$('train-gradient-checkpoint').checked }; for (const k of ['epochs','learningRate','batchSize','gradientAccumulation','maxLength','loraRank','saveEvery','maxSteps']) body[k]=Number($(`train-${k}`).value); renderTrainer(await ctx.api('/api/trainer/start',{ method:'POST',body })); } catch (error) { ctx.fail(error); } };
  for (const [id,action] of [['training-pause','pause'],['training-resume','resume'],['training-cancel','cancel']]) $(id).onclick=async () => { try { renderTrainer(await ctx.api('/api/trainer/control',{ method:'POST',body:{ action } })); } catch (error) { ctx.fail(error); } };
}
async function tick(data) {
  pollCount++;
  await modelConversionUI?.tick();
  if (ctx.state.view==='trainer') { try { const result=await ctx.api('/api/trainer'); data.trainer=result; renderTrainer(result); if (result.loras) { data.loras=result.loras; renderAdapters(result.loras); const adapter=result.loras.adapters.find(a => a.sourceJobId===result.job?.id); if (result.job?.status==='completed' && adapter && !namedJobs.has(result.job.id) && adapter.name==='Untitled LoRA') { namedJobs.add(result.job.id); const name=await ctx.askPath('Name your trained LoRA','Training is complete. Choose the name to use in your trained adapter library.','My trained LoRA'); if (name) { await ctx.api('/api/adapters/rename',{ method:'POST',body:{ id:adapter.id,name } }); await ctx.refresh(); } } } } catch {} }
  if (ctx.state.view==='settings' && activePanel==='explore') { try { data.downloads=await ctx.api('/api/downloads'); renderDownloads(data.downloads); } catch {} }
  if (ctx.state.view==='settings' && ['runtime','instances','api'].includes(activePanel)) { if (pollCount%3===0) { try { data.hardware=await ctx.api('/api/hardware'); data.localApi=await ctx.api('/api/local-api'); } catch {} } renderRuntime(data); renderInstances(data); renderApi(data.localApi); }
}
